/* @lc app=leetcode id=2003 lang=kotlin */ class Solution { fun mk(vis: BooleanArray, pr: BooleanArray, v: Int, x: Int) = true.also { vis[v] = true }.also { pr[x] = true } fun smallestMissingValueSubtree(parents: IntArray, nums: IntArray): IntArray = parents.size.let { n -> IntArray(n) { 1 }.also { ans -> nums.indexOf(1).takeIf { it >= 0 }?.let { s -> parents.indices.groupBy { parents[it] }.let { g -> BooleanArray(n).let { vis -> BooleanArray(n + 2).let { pr -> generateSequence(s) { parents[it].takeIf { p -> p >= 0 } }.fold(1) { mex, u -> generateSequence(listOf(u).filter { !vis[it] }.onEach { mk(vis, pr, it, nums[it]) }) { f -> f.flatMap { g[it].orEmpty() }.filter { !vis[it] }.onEach { mk(vis, pr, it, nums[it]) }.takeIf { it.isNotEmpty() } }.count().let { generateSequence(mex) { it + 1 }.first { !pr[it] } }.also { ans[u] = it } } } } } } } } }